// --- added v5.4.9: previously untranslated keys ---
about_disclaimer_title: "إخلاء المسؤولية",
about_disclaimer_purpose: "يُقدَّم ps5upload لأغراض البحث والتعليم وقابلية التشغيل البيني وتطوير البرمجيات المنزلية فقط. وهو غير تابع لشركة Sony Interactive Entertainment Inc. وغير معتمد منها أو مرتبط بها. «PlayStation» و«PS5» علامتان تجاريتان مملوكتان لشركة Sony Interactive Entertainment Inc.، وتُستخدمان هنا لأغراض التعريف فقط.",
about_disclaimer_piracy: "استخدمه فقط مع أجهزة تملكها ومحتوى تملكه بصورة قانونية. ولا يجوز استخدامه لنسخ برامج لا تملك حق استخدامها أو توزيعها أو تشغيلها.",
about_disclaimer_risk: "يُقدَّم هذا البرنامج «كما هو» دون أي ضمان من أي نوع. قد يؤدي تشغيل جهاز معدَّل إلى تلفه بشكل دائم، وإلى إتلاف ملفات الحفظ والتراخيص بصورة لا رجعة فيها، وإلى حظر حسابك أو جهازك. أنت تستخدمه على مسؤوليتك الكاملة وتتحمل المسؤولية التامة عن العواقب. انسخ احتياطيًا كل ما لا يمكنك تحمل فقدانه قبل أن تبدأ.",
