edit_session_body: "ما دامت هذه الجلسة مفتوحة تبقى اللعبة مخفية عن الشاشة الرئيسية لجهاز PS5، لأن ShadowMount+ لا يرى الصورة في موضعها الحالي. أنهِ التحرير لإعادتها إلى مكانها.",
