"joberr.ava1_refused": "رفضت PS5 هذا الطلب (الرمز {code}). أعد المحاولة؛ وإذا تكرر ذلك فحدّث المساعد والتطبيق إلى الإصدار نفسه وأرفق الرمز في تقرير الخطأ.",
"joberr.ava1_busy": "مساعد PS5 مشغول ولم يقبل هذا النقل في الوقت المناسب. انتظر حتى ينتهي من عمله الآخر ثم انقر على إعادة المحاولة.",
"joberr.ava1_unreachable": "تعذّر الوصول إلى PS5. تحقق من أنها قيد التشغيل وعلى الشبكة نفسها وأن المساعد يعمل، ثم انقر على إعادة المحاولة.",
"joberr.ava1_exists": "الوجهة موجودة بالفعل على PS5. اختر الكتابة فوق لاستبدالها، أو اختر وجهة أخرى.",
"joberr.ava1_commit_exists": "تم رفع الملف لكن تعذّر نشره لأن الوجهة موجودة بالفعل. اختر الكتابة فوق لاستبدالها، أو اختر وجهة أخرى.",
"joberr.ava1_cross_device": "الوجهة على محرك مختلف عن منطقة التجهيز، لذا لم تستطع PS5 نقل الملف. اختر وجهة على المحرك نفسه أو ارفع أولاً إلى المحرك الداخلي.",
"joberr.ava1_wrong_console": "الجهاز على هذا العنوان ليس PS5 المقترنة بهذا التطبيق. تحقق من العنوان أو أعد الاقتران بهذه الوحدة.",
"joberr.ava1_no_identity": "ليس لدى هذا التطبيق هوية اقتران بعد. اقترن بـ PS5 من شاشة الاتصال ثم أعد المحاولة.",
"joberr.zip_read_error": "تعذّرت قراءة ملف .zip (ربما اختفى الملف أو محركه أثناء القراءة). تأكد من أن المصدر لا يزال متصلاً ثم انقر على إعادة المحاولة.",
"joberr.ava1_zip_corrupt": "تعذّرت قراءة ملف .zip هذا: إنه تالف أو غير مكتمل. نزّله أو أنشئه من جديد ثم أعد المحاولة.",
"joberr.ava1_7z_corrupt": "تعذّرت قراءة ملف .7z هذا: إنه تالف أو غير مكتمل. نزّله أو أنشئه من جديد ثم أعد المحاولة.",
"joberr.ava1_7z_encrypted": "ملف .7z هذا مشفّر ولا يمكن بثه. فك ضغطه على حاسوبك وارفع المجلد بدلاً منه.",
"joberr.ava1_7z_unsafe_path": "يحتوي ملف .7z هذا على مسار ملف غير آمن (يخرج من مجلده). فك ضغطه على حاسوبك وارفع المجلد بدلاً منه.",
"joberr.rar_password": "يحتاج ملف .rar هذا إلى كلمة مرور، أو أن كلمة المرور المُدخلة خاطئة. أدخل كلمة المرور الصحيحة وأعد المحاولة.",
"joberr.rar_corrupt": "ملف .rar هذا تالف، أو بعض أجزائه مفقودة أو بترتيب خاطئ. تأكد من وجود كل الأجزاء ثم أعد المحاولة.",
"joberr.ava1_copy_lost": "فقدت PS5 أثر عملية النسخ هذه (أُعيد تشغيل المساعد أو انقطع الاتصال). انقر على إعادة المحاولة لبدئها من جديد.",
"joberr.ava1_copy_failed": "تعذّر على PS5 إكمال النسخ. تحقق من المساحة الحرة ومن أن المصدر والوجهة لا يزالان متاحين ثم أعد المحاولة.",
"joberr.ava1_local_io": "تعذّر على هذا الحاسوب كتابة الملف الذي تم تنزيله. تحقق من أذونات مجلد الوجهة ومساحته الحرة ثم أعد المحاولة.",
"joberr.ava1_bad_manifest": "أرسلت PS5 قائمة ملفات لم يفهمها هذا التطبيق. حدّث المساعد والتطبيق إلى الإصدار نفسه ثم أعد المحاولة.",
"joberr.helper_not_ava1": "مساعد PS5 لا يعمل. أرسله من شاشة الاتصال (أو استخدم تحديث المساعد إذا عرضه الشريط) ثم أعد المحاولة.",
"joberr.helper_not_ava1_web": "مساعد PS5 لا يعمل. لا تستطيع واجهة الويب هذه إرساله: شغّل حمولة ps5upload على الجهاز بمحمّل الحمولات المعتاد لديك (أو استخدم تحديث المساعد إذا عرضه الشريط) ثم أعد المحاولة.",
"joberr.not_paired": "لم تقبل هذه PS5 هذا التطبيق بعد. اقرنهما (زر اقتران…) ثم أعد المحاولة.",
