"arcpkg.choose": "اختر أرشيفًا…",
"arcpkg.help": "لملف ‎.zip أو ‎.7z أو ‎.rar يحتوي على ملف ‎.pkg واحد أو أكثر داخل أي مجلد. تُفك الحزم فقط، مباشرة إلى PS5 (لا يُستخرج شيء على هذا الحاسوب)، ثم تُثبَّت واحدة تلو الأخرى: اللعبة الأساسية أولًا، ثم تحديثها، ثم المحتوى الإضافي. أرشيف RAR متعدد الأجزاء (‎.part1.rar، ‎.part2.rar…) مدعوم: اختر الجزء الأول وأبقِ البقية بجانبه. تُطلب كلمة المرور عندما يحتاجها RAR؛ أما ZIP و7z المحميان بكلمة مرور فغير مدعومين.",
"arcpkg.keepsRunning": "يستمر هذا في العمل إذا فتحت شاشة أخرى، ويظهر أيضًا في «المهام».",
"arcpkg.notArchive": "هذا الملف ليس أرشيف ‎.zip أو ‎.7z أو ‎.rar.",
"arcpkg.pick": "اختر أرشيفًا",
"arcpkg.title": "تثبيت الحزم من أرشيف",
"install.library.title": "نسخ الحزم على PS5",
"install.stream.file.help": "اختر ملف ‎.pkg أو ‎.fpkg، أو أفلته في أي مكان من هذه النافذة. أبقِ التطبيق مفتوحًا حتى ينتهي التثبيت؛ يظهر التقدم في قائمة الانتظار أعلاه وفي «المهام».",
"install.stream.file.title": "تثبيت ملف حزمة",
"install.tab.stream.lead": "يثبّت PS5 مباشرة من هذا الحاسوب أو من رابط. لا توضع نسخة على PS5 أولًا، لذلك لا حاجة إلى مساحة فارغة هناك، وهذه أكثر طرق التثبيت موثوقية.",
"install.tab.upload.lead": "تُنسخ الحزمة إلى PS5 أولًا، ثم تُثبَّت من تلك النسخة. استخدم هذا عندما لا يستطيع PS5 الوصول إلى هذا الحاسوب (يفشل البث بخطأ في الشبكة)، أو لإبقاء الحزم على PS5 وإعادة تثبيتها لاحقًا دون هذا الحاسوب.",
"install.upload.file.browser": "نسخ حزمة إلى PS5 من هنا يتطلب تطبيق سطح المكتب. في واجهة الويب استخدم «بث وتثبيت»، أو ثبّت أدناه الحزم الموجودة مسبقًا على PS5.",
"install.upload.file.help": "اختر ملف ‎.pkg أو ‎.fpkg. تحتاج النسخة إلى مساحة فارغة على PS5 بحجم الحزمة كاملة، وتبقى في القائمة أدناه إلى أن تحذفها.",
"install.upload.file.title": "نسخ حزمة إلى PS5 وتثبيتها",
"linkcard.confirm.direct": "ينزّل PS5 الحزمة من الرابط بنفسه ويثبّتها. لا حاجة إلى هذا الحاسوب بعد البدء، ويظهر التقدم على PS5 (التنزيلات) وليس هنا. إذا لم يستطع PS5 الوصول إلى الرابط، يمرّره التطبيق عبر هذا الحاسوب. إعادة التثبيت فوق لعبة مثبتة قد تحذفها إذا فشل مثبّت Sony. استخدم فقط روابط الحزم التي تثق بها ويحق لك تثبيتها.",
"linkcard.confirm.download": "يحفظ هذا الحاسوب الحزمة كاملة على القرص أولًا، ثم يثبّتها على PS5. يجب أن يبقى قيد التشغيل حتى تنتهي الخطوتان، ويحتاج إلى مساحة فارغة للحزمة. إعادة التثبيت فوق لعبة مثبتة قد تحذفها إذا فشل مثبّت Sony. استخدم فقط روابط الحزم التي تثق بها ويحق لك تثبيتها.",
"linkcard.confirm.stream": "ينزّل هذا الحاسوب الحزمة ويمرّرها مباشرة إلى PS5، لذلك يجب أن يبقى قيد التشغيل ومتصلًا حتى ينتهي التثبيت. لا يُحفظ شيء على القرص. إعادة التثبيت فوق لعبة مثبتة قد تحذفها إذا فشل مثبّت Sony. استخدم فقط روابط الحزم التي تثق بها ويحق لك تثبيتها.",
