stop: "إيقاف",
activity_description_v2: "كل ما يفعله التطبيق وما فعله على أجهزتك: عمليات الرفع والتنزيل والتثبيت وعمليات الملفات. أوقف أيًّا منها أو أعد محاولته من هنا. يُحتفظ بآخر 100 عملية، حتى بعد إعادة التشغيل.",
disk_usage_description_v2: "اعرف ما الذي يشغل المساحة على PS5. كل مربع هو مجلد بحجم يتناسب مع محتواه؛ انقر مربعًا لترى ما بداخله.",
fw_spoof_subtitle_v2: "يتحقق مما إذا كان إصدار البرنامج الثابت الذي يبلّغ عنه هذا الـPS5 قد غيّره بايلود تمويه، لتعرف الإصدار الحقيقي قبل تثبيت شيء يعتمد عليه.",
health_subtitle_v2: "يتحقق من أن PS5 وهذا التطبيق والشبكة بينهما تعمل، ويخبرك بما يجب إصلاحه إن لم تكن تعمل، ويقيس سرعة نقل الملفات بينهما.",
